func TestResolveLatestCheckpointFromMap(t *testing.T) {
	t.Parallel()

	now := time.Now()
	older := now.Add(-1 * time.Hour)
	oldest := now.Add(-2 * time.Hour)

	mapWithThree := map[CheckpointID]CheckpointInfo{
		"aaa111bbb222": {CheckpointID: "aaa111bbb222", CreatedAt: oldest},
		"ccc333ddd444": {CheckpointID: "ccc333ddd444", CreatedAt: now},
		"eee555fff666": {CheckpointID: "eee555fff666", CreatedAt: older},
	}

	t.Run("single ID returns it directly", func(t *testing.T) {
		t.Parallel()
		info, found := resolveLatestCheckpointFromMap(
			[]CheckpointID{"aaa111bbb222"},
			mapWithThree,
		)
		if !found {
			t.Fatal("expected found=true")
		}
		if info.CheckpointID != "aaa111bbb222" {
			t.Errorf("got %s, want aaa111bbb222", info.CheckpointID)
		}
	})

	t.Run("multiple IDs returns latest by CreatedAt", func(t *testing.T) {
		t.Parallel()
		info, found := resolveLatestCheckpointFromMap(
			[]CheckpointID{"aaa111bbb222", "ccc333ddd444", "eee555fff666"},
			mapWithThree,
		)
		if !found {
			t.Fatal("expected found=true")
		}
		if info.CheckpointID != "ccc333ddd444" {
			t.Errorf("got %s, want ccc333ddd444 (the newest)", info.CheckpointID)
		}
	})

	t.Run("IDs not in map are skipped", func(t *testing.T) {
		t.Parallel()
		info, found := resolveLatestCheckpointFromMap(
			[]CheckpointID{"nonexistent00", "aaa111bbb222"},
			mapWithThree,
		)
		if !found {
			t.Fatal("expected found=true")
		}
		if info.CheckpointID != "aaa111bbb222" {
			t.Errorf("got %s, want aaa111bbb222", info.CheckpointID)
		}
	})

	t.Run("all IDs missing from map returns not found", func(t *testing.T) {
		t.Parallel()
		_, found := resolveLatestCheckpointFromMap(
			[]CheckpointID{"nonexistent00", "alsonotthere"},
			mapWithThree,
		)
		if found {
			t.Error("expected found=false when no IDs match")
		}
	})

	t.Run("empty ID list returns not found", func(t *testing.T) {
		t.Parallel()
		_, found := resolveLatestCheckpointFromMap(
			[]CheckpointID{},
			mapWithThree,
		)
		if found {
			t.Error("expected found=false for empty list")
		}
	})
}

